css:
.card.sunny {
  width: 280px;
  height: 280px;
  background: linear-gradient(180deg, #ffb347 0%, #ff8c42 100%);
  border-radius: 36px;
  position: relative;
  overflow: hidden;
  font-family: "Courier New", Courier, monospace;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.35);
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  user-select: none;
}

.card.sunny:hover {
  transform: translateY(-8px);
  box-shadow: 0 30px 60px rgba(0, 0, 0, 0.45);
}

.sky {
  position: absolute;
  inset: 0;
  z-index: 1;
}

.sun-container {
  position: absolute;
  top: 35px;
  right: 35px;
  width: 50px;
  height: 50px;
}

.sun-core {
  width: 100%;
  height: 100%;
  background: #fff;
  border-radius: 4px;
  box-shadow:
    0 0 25px #fff,
    0 0 50px #ffea00;
  z-index: 2;
  position: relative;
}

.sun-glow {
  position: absolute;
  inset: -15px;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 0.4) 0%,
    transparent 70%
  );
  animation: sunPulse 3s ease-in-out infinite;
}

@keyframes sunPulse {
  0%,
  100% {
    transform: scale(1);
    opacity: 0.5;
  }
  50% {
    transform: scale(1.3);
    opacity: 0.8;
  }
}

.landscape {
  position: absolute;
  bottom: 0;
  width: 100%;
  height: 45%;
  shape-rendering: crispEdges;
}

.content {
  position: relative;
  z-index: 10;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  color: white;
}

.main-temp {
  padding: 35px 25px 0;
  filter: drop-shadow(3px 3px 0px rgba(0, 0, 0, 0.1));
}

.pixel-svg {
  width: 110px;
  height: auto;
  shape-rendering: crispEdges;
}

.current-status {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 30px;
  margin-top: -20px;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  font-size: 13px;
  text-shadow: 2px 2px 0px rgba(0, 0, 0, 0.15);
}

.icon-weather {
  width: 22px;
  height: 22px;
  shape-rendering: crispEdges;
}

.forecast {
  display: flex;
  justify-content: space-between;
  padding: 22px 30px;
  background: rgba(255, 255, 255, 0.15);
  backdrop-filter: blur(12px) saturate(150%);
  -webkit-backdrop-filter: blur(12px) saturate(150%);
  border-top: 1px solid rgba(255, 255, 255, 0.3);
  box-shadow: 0 -5px 15px rgba(0, 0, 0, 0.05);
  border-radius: 0 0 35px 35px;
}

.day-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  opacity: 0.75;
}

.day-col.active {
  opacity: 1;
  text-shadow: 0 0 10px rgba(255, 255, 255, 0.5);
}

.day-label {
  font-size: 10px;
  font-weight: 800;
  color: #fff;
}

.day-val {
  font-size: 15px;
  font-weight: bold;
}

.scanlines {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to bottom,
    transparent 50%,
    rgba(0, 0, 0, 0.04) 50%
  );
  background-size: 100% 4px;
  pointer-events: none;
  z-index: 20;
}
